To address the identified security and correctness issues, we'll implement the following improvements:

1. **Directory Permissions**: Create directories with `0700` permissions to restrict access to the owner only.
2. **File Permissions**: Set file permissions during creation using `fopen` with appropriate flags and modes.
3. **Error Handling**: Check the return values of all system calls to handle errors gracefully.
4. **Path Sanitization**: Ensure input paths do not contain malicious characters that could lead to path traversal attacks.
5. **Information Leakage Prevention**: Avoid leaking sensitive information by properly handling error conditions without exposing internal system details.

Here is the improved implementation:

```cpp
#include <fstream>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <string>
#include <stdexcept>

using namespace std;

void saveSecreteFile(const string& directory, const string& filename, const string& content) {
    // Sanitize input paths to prevent path traversal attacks
    if (filename.find("..") != string::npos) {
        throw invalid_argument("Filename contains invalid characters");
    }

    // Create the directory with secure permissions
    struct stat dirInfo;
    int dirStatus = stat(directory.c_str(), &dirInfo);

    if (dirStatus != 0) {
        mode_t nDirMode = S_IRWXU; // Owner can read, write, execute
        int mkdirStatus = mkdir(directory.c_str(), nDirMode);

        if (mkdirStatus != 0 && errno != EEXIST) {
            throw runtime_error("Failed to create directory");
        }
    } else {
        // Verify existing directory permissions are secure
        if ((dirInfo.st_mode & S_IRWXU) != S_IRWXU) {
            throw runtime_error("Directory does not have proper permissions");
        }
    }

    string fullPath = directory + "/" + filename;

    // Open the file with exclusive access and set permissions atomically
    int fd = open(fullPath.c_str(), O_CREAT | O_WRONLY | O_CLOEXEC, S_IRUSR | S_IWUSR);

    if (fd == -1) {
        throw runtime_error("Failed to create file");
    }

    // Write content to the file
    ssize_t bytesWritten = write(fd, content.c_str(), content.size());

    if (bytesWritten != static_cast<ssize_t>(content.size())) {
        close(fd);
        throw runtime_error("Failed to write to file");
    }

    close(fd);
}
```

