using namespace std;

int main() {
    string directory = "./secret_dir";
    string filename = "secret_file.txt";
    string content = "This is a secret content.";

    try {
        saveSecreteFile(directory, filename, content);

        // Verify file exists and has correct permissions
        struct stat fileInfo;
        if (stat((directory + "/" + filename).c_str(), &fileInfo) != 0) {
            cout << "File does not exist." << endl;
            return 1;
        }

        // Check if only owner has read/write access
        if ((fileInfo.st_mode & S_IRUSR) && (fileInfo.st_mode & S_IWUSR) &&
            !(fileInfo.st_mode & S_IRGRP) && !(fileInfo.st_mode & S_IROTH)) {
            cout << "File permissions are correct." << endl;
        } else {
            cout << "File permissions are incorrect." << endl;
            return 1;
        }

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
